script:
frappe.ui.form.on("User", {
    refresh: async function (frm) {
        if (frm.doc.__islocal) return;

        const user_id = frm.doc.name;

        const settings_enabled = await frappe.call({
            method: "recruitment.recruitment.doctype.microsoft_teams_app_settings.microsoft_teams_app_settings.is_teams_enabled"
        }).then(r => r.message);

        if (!settings_enabled) return;

        const settings = await frappe.db.get_doc("Microsoft Teams App Settings");
        const required_filled = settings.client_id && settings.client_secret && settings.tenant_id && settings.redirect_uri && settings.tenant_domain;

        if (!required_filled) return;

        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Microsoft Teams User Token",
                filters: { user: user_id },
                fieldname: "name"
            },
            callback(res) {
                if (!res.message || Object.keys(res.message).length === 0) {
                    frm.add_custom_button("Authorize Teams", () => {
                        frappe.call({
                            method: "recruitment.customizations.interview.interview.get_teams_auth_url",
                            args: { user_id: user_id },
                            callback(r) {
                                if (r.message) {
                                    window.open(r.message, "_blank");
                                }
                            }
                        });
                    });
                }
            }
        });
    }
});
